#include <stdio.h>
#include <string.h>
#include <stdbool.h>

char words[5005][16];
bool visited[5005];
int queue_idx[5005];
int queue_dist[5005];

bool diff1(const char *a, const char *b, int len) {
    int diff = 0;
    for (int i = 0; i < len; i++) {
        if (a[i] != b[i]) if (++diff > 1) return false;
    }
    return diff == 1;
}

int main() {
    char begin_word[16], end_word[16];
    if (scanf("%s %s", begin_word, end_word) != 2) return 0;
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int target_idx = -1;
    int wlen = strlen(begin_word);
    for (int i = 0; i < n; i++) {
        scanf("%s", words[i]);
        if (strcmp(words[i], end_word) == 0) target_idx = i;
    }
    if (target_idx == -1) { printf("0\n"); return 0; }
    int qh = 0, qt = 0;
    for (int i = 0; i < n; i++) {
        if (diff1(begin_word, words[i], wlen)) {
            visited[i] = true;
            queue_idx[qt] = i;
            queue_dist[qt++] = 2;
        }
    }
    while (qh < qt) {
        int curr = queue_idx[qh];
        int dist = queue_dist[qh++];
        if (curr == target_idx) { printf("%d\n", dist); return 0; }
        for (int i = 0; i < n; i++) {
            if (!visited[i] && diff1(words[curr], words[i], wlen)) {
                visited[i] = true;
                queue_idx[qt] = i;
                queue_dist[qt++] = dist + 1;
            }
        }
    }
    printf("0\n");
    return 0;
}
